function weeklyReview(opts){
  opts=opts||{};
  var week=(opts.week||'本周').trim()||'本周';
  var done=String(opts.done||'').split(/[\n,，;；]+/).map(function(s){return s.trim();}).filter(Boolean);
  var next=String(opts.next||'').split(/[\n,，;；]+/).map(function(s){return s.trim();}).filter(Boolean);
  var L=[];
  L.push('# 周报复盘 · '+week);
  L.push('');
  L.push('## 本周完成');
  if(done.length){ for(var i=0;i<done.length;i++) L.push('- [x] '+done[i]); }
  else { L.push('- [x] ____'); }
  L.push('');
  L.push('## 数据 / 进展');
  L.push('- 指标：____（周环比 ____）');
  L.push('');
  L.push('## 下周计划');
  if(next.length){ for(var j=0;j<next.length;j++) L.push('- [ ] '+next[j]); }
  else { L.push('- [ ] ____'); }
  L.push('');
  L.push('## 做得好 / 待改进');
  L.push('- 继续保持：');
  L.push('- 需要改进：');
  L.push('');
  L.push('## 风险与求助');
  L.push('- ');
  return L.join('\n');
}

var EXPORTS={weeklyReview:weeklyReview};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WeeklyReviewForgePure = EXPORTS; }
